   670	            self.handler.deinit();
   671	        }
   672	
   673	        /// Write the current continuation suffix directly to a caller-owned
   674	        /// writer. The caller must pause and serialize access to this Stream.
   675	        pub fn writeContinuation(
   676	            self: *const Self,
   677	            writer: *std.Io.Writer,
   678	        ) (std.Io.Writer.Error || error{
   679	            ContinuationDisabled,
   680	            ContinuationUnavailable,
   681	        })!void {
   682	            const tracker = self.continuation orelse
   683	                return error.ContinuationDisabled;
