   688	
   689	        /// True when no continuation suffix is needed to reproduce the
   690	        /// stream's current parsing state.
   691	        pub inline fn ground(self: *const Self) bool {
   692	            // Parser ground alone is not sufficient because the UTF-8
   693	            // decoder may have some state.
